  $"FF00000FFF0FFF7FFAFFEFFDFFFF"	  $"FFFFFFF0FF0FF7FFAFFEFFDFFFFF"	  $"FFFFFFFF0F0FFFFFAFFEFFDFFFFF"	  $"FFFFFFFFF00FFFFFFFEFFDFFFFFF"	  $"FFFFFFFFFF0FFFFFFFFFDFFFFFFF"	  $"FFFFFFFFFFFFFFFFFFFFFFFFFFFF"	  $"FFFFFFFFFFFFFFFFFFFFFFFFFFFF"	  $"FFFFFFFFFFFFFFFFFFFFFFFFFFFF",	  $"0000000000000000000000000000"	  $"0000000000000000000000000000"	  $"0000000000000000000000000000"	  $"0000000000000000000000000000"	  $"0000000000F000000000F0000000"	  $"000000000FF0000000F00F000000"	  $"00000000FFF00000F00F00F00000"	  $"0000000FFFF00F00F00F00F00000"	  $"00FFFFFFFFF000F00F00F00F0000"	  $"0FFFFFFFFFF000F00F00F00F0000"	  $"0FFFFFFFFFF000F00F00F00F0000"	  $"0FFFFFFFFFF000F00F00F00F0000"	  $"00FFFFFFFFF000F00F00F00F0000"	  $"0000000FFFF00F00F00F00F00000"	  $"00000000FFF00000F00F00F00000"	  $"000000000FF0000000F00F000000"	  $"0000000000F000000000F0000000"	  $"0000000000000000000000000000"	  $"0000000000000000000000000000"	  $"0000000000000000000000000000";};read rCDEVCode (1,Convert) "Sound.Load";read rCodeResource(1,Convert) "ReqProc.Load";resource rCDEVFlags (1) {	wantHit+wantInit+wantCreate+wantAbout+	updateSSfromBRAM+wantBoot+wantClose+	wantRun+wantEvents+wantEdit,				/* CDEV Flags */	1,											/* Enabled */	1,											/* Version */	1,											/* Machine */	4,											/* System */	{0,0,142-5-40,300},							/* DataRect */	"Sound",									/* Name */	"Dave Lyons",								/* Author */	"v2.1";									/* VersStr */};// --- Control List Definitionsresource rControlList (CTLLST_00000001, preload) {       {       CTLTMP_00000001,        // control 1       CTLTMP_00000002,        // control 2       CTLTMP_00000003,        // control 3       CTLTMP_00000004,        // control 4       CTLTMP_00000005,        // control 5       CTLTMP_00000009,        // control 9       CTLTMP_0000000A,        // control 10       };};// --- Control Templates// Volume scrollerresource rControlTemplate (CTLTMP_00000002, preload) {       $00000001,              // ID       {  6, 20, 19,196+20},      // rect       ScrollControl {{               $001C,          // flag               $1002,          // moreFlags               $00000000,      // refCon               $0010,          // maxSize               $0002,          // viewSize               $0000,          // initialValue               0               // colorTableRef       }};};// Pitch scrollerresource rControlTemplate (CTLTMP_00000001, preload) {       $00000002,              // ID       { 23, 20, 36,196+20},      // rect       ScrollControl {{               $001C,          // flag               $1002,          // moreFlags               $00000000,      // refCon               $0010,          // maxSize               $0002,          // viewSize               $0000,          // initialValue               0               // colorTableRef       }};};// Pitch labelresource rControlTemplate (CTLTMP_00000003, preload) {       $00000003,              // ID       { 25,206+20,34,253+20},      // rect       statTextControl {{               $0004,          // flag               $1002,          // moreFlags               $00000000,      // refCon               LETXTBOX_00000001,     // textRef               0,              // textSize               $0000           // just       }};};resource rTextForLETextBox2 (LETXTBOX_00000001, preload) { "Pitch" };// Volume labelresource rControlTemplate (CTLTMP_00000004, preload) {       $00000004,              // ID       {  8,206+20,18,271+20},      // rect       statTextControl {{               $0004,          // flag               $1002,          // moreFlags               $00000000,      // refCon               LETXTBOX_00000002,     // textRef               0,              // textSize               $0000           // just       }};};resource rTextForLETextBox2 (LETXTBOX_00000002, preload) { "Volume" };// Check box "Visual Indication of Sounds"resource rControlTemplate (CTLTMP_00000005, preload) {       $00000005,              // ID       { 43, 20, 53,282},      // rect       checkControl {{               $0000,          // flag               $3002,          // moreFlags               $00000000,      // refCon               PSTR_00000001,  // titleRef               $0000,          // initialValue               0,              // colorTableRef               {"G","g",$0000,$0000}  // key equivalents       }};};resource rPString (PSTR_00000001, preload) { "Give visual indication of sounds" };// *******************************************************************//// Event pop-up//// *******************************************************************resource rControlTemplate (CTLTMP_00000009, preload) {       $00000009,              // ID       { 61, 36, 73, 265},      // rect       popUpControl {{               $0042,          // flag               $1082,          // moreFlags               $00000000,      // refCon               $0000,          // titleWidth               MENU_00000003,  // menuRef               $FFFE,          // initialValue               0               // colorTableRef       }};};resource rMenu (MENU_00000003, preload) {       $0001,                  // menuID       $A000,                  // menuFlag       PSTR_00000007, {        // menuTitleRef               MENUITEM_00000127,               MENUITEM_00000120  /* divider */       };};resource rPString (PSTR_00000007, preload) { " Event " };// System Beepresource rMenuItem (MENUITEM_00000127, preload) {       $FFFE,                  // itemID       "","",                  // itemChar, itemAltChar       NIL,                    // itemCheck       $8000,                  // itemFlag       PSTR_00000127           // itemTitleRef};resource rPString (PSTR_00000127, preload) { "System Beep" };/*  rTaggedStrings(1) lists the event names for the Event pop-up,  in order of appearance, with their corresponding SysBeep2  codes.*/resource rTaggedStrings(1,preload,locked,fixed) {{	$0050, "Attention",	$0033, "Bad disk",	$0008, "Bad keypress",	$0009, "Bad input value",	$0004, "Can’t click there",	$0054, "Caution alert",	$0014, "Disk ejected",	$0013, "Disk inserted",	$0030, "Disk request",	$0043, "Empty trash",	$0042, "Fill trash",	$000A, "Input field full",	$0053, "Note alert",	$0052, "Stop alert",	$0031, "System startup",	$0015, "System shutdown",	$0005, "Task completed",	$000C, "Task failed",	$000B, "Task impossible",	$0041, "Whoosh closed",	$0040, "Whoosh open",	$0100, "You Have Mail"}};// *******************************************************************//// Sound pop-up//// *******************************************************************resource rControlTemplate (CTLTMP_0000000A, preload) {       $0000000A,              // ID       { 77, 36, 89, 265},      // rect       popUpControl {{               $0042,          // flag               $1082,          // moreFlags               $00000000,      // refCon               $0000,          // titleWidth               MENU_00000004,  // menuRef               $0001,          // initialValue               0               // colorTableRef       }};};resource rMenu (MENU_00000004, preload) {       $0001,                  // menuID       $A000,                  // menuFlag       PSTR_00000009, {        // menuTitleRef               MENUITEM_00000123, /* "Not assigned" */               MENUITEM_00000120, /* ------- */               MENUITEM_00000122, /* Silence */               MENUITEM_00000004, /* Standard Beep */               MENUITEM_0000F001  /* ------- */       };};resource rPString (PSTR_00000009, preload) { " Sound " };resource rMenuItem (MENUITEM_00000120, preload) {       $F000,                  // itemID       "","",                  // itemChar, itemAltChar       NIL,                    // itemCheck       $8080,                  // itemFlag       PSTR_00000120           // itemTitleRef};// Item F001--dividing line that I kill if there are no soundsresource rMenuItem (MENUITEM_0000F001, preload) {       $F001,                  // itemID       "","",                  // itemChar, itemAltChar       NIL,                    // itemCheck       $8080,                  // itemFlag       PSTR_00000120           // itemTitleRef};resource rPString (PSTR_00000120, preload) { "-" };// Not Assigned (1)resource rMenuItem (MENUITEM_00000123, preload) {       $0001,                  // itemID       "","",                  // itemChar, itemAltChar       NIL,                    // itemCheck       $8000,                  // itemFlag       PSTR_00000123           // itemTitleRef};resource rPString (PSTR_00000123, preload) { "Not assigned" };// Silence (2)resource rMenuItem (MENUITEM_00000122, preload) {       $0002,                  // itemID       "","",                  // itemChar, itemAltChar       NIL,                    // itemCheck       $8000,                  // itemFlag       PSTR_00000122           // itemTitleRef};resource rPString (PSTR_00000122, preload) { "Silence" };// Standard Beep (3)resource rMenuItem (MENUITEM_00000004, preload) {       $0003,                  // itemID       "","",                  // itemChar, itemAltChar       NIL,                    // itemCheck       $8000,                  // itemFlag       PSTR_0000000A           // itemTitleRef};resource rPString (PSTR_0000000A, preload) { "Standard Beep" };//// --- obsolete stuff//// resource rPString (PSTR_00000003, preload) { " Sound In " };//   resource rPString (PSTR_00000004, preload) { "Apple Mic. Jack" };//   resource rPString (PSTR_00000107, preload) { "Sound Exp. Pins" };//// Record... button// resource rControlTemplate (CTLTMP_00000006, preload) {//        $00000006,              // ID//        {121-4, 80,135-4,218},      // rect//        simpleButtonControl {{